package com.gdjztech.ringconn.ui;

public class DashboardHtml {
    public static String getHtml() {
        StringBuilder sb = new StringBuilder(38000);
        sb.append("<!DOCTYPE html>\n<html lang=\"de\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no\">\n    <title>Intervals Direct & Coach Hub</title>\n    <style>\n        :root {\n            --bg: #070A11;\n            --card-bg: rgba(22, 31, 48, 0.88);\n            --card-border: #1E293B;\n            --card-border-glow: rgba(56, 189, 248, 0.25);\n            --text-primary: #F8FAFC;\n            --text-secondary: #94A3B8;\n            --text-muted: #64748B;\n            --accent: #38BDF8;\n            --accent-gradient: linear-gradient(135deg, #0284C7, #38BDF8);\n            --success: #10B981;\n            --warning: #F59E0B;\n            --danger: #EF4444;\n            --deep: #6366F1;\n            --rem: #06B6D4;\n            --light: #3B82F6;\n            --awake: #64748B;\n        }\n        * { box-sizing: border-box; margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif; -webkit-tap-highlight-color: transparent; }\n        body { background-color: var(--bg); color: var(--text-primary); padding: 16px; padding-bottom: 38px; min-height: 100vh; }\n        .header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 18px; padding-top: 6px; }\n        .brand { display: flex; align-items: center; gap: 12px; }\n        .brand-icon { width: 38px; height: 38px; border-radius: 12px; background: var(--accent-gradient); display: flex; align-items: center; justify-content: center; font-size: 20px; color: #fff; box-shadow: 0 4px 16px rgba(56,189,248,0.35); }\n        .brand h1 { font-size: 19px; font-weight: 800; letter-spacing: -0.4px; background: linear-gradient(180deg, #FFFFFF, #CBD5E1); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }\n        .brand p { font-size: 11px; color: var(--text-secondary); margin-top: 1px; }\n        .close-btn { background: #111827; border: 1px solid var(--card-border); color: var(--text-secondary); width: 36px; height: 36px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 18px; cursor: pointer; transition: all 0.2s; }\n        .close-btn:active { background: #1E293B; color: #fff; transform: scale(0.95); }\n        .nav-tabs { display: flex; background: #0F172A; border-radius: 14px; padding: 4px; margin-bottom: 18px; border: 1px solid var(--card-border); overflow-x: auto; }\n        .nav-btn { flex: 1; padding: 10px 0; background: transparent; border: none; color: var(--text-secondary); font-size: 12px; font-weight: 600; border-radius: 10px; cursor: pointer; transition: all 0.2s; white-space: nowrap; text-align: center; }\n        .nav-btn.active { background: var(--accent); color: #070A11; font-weight: 700; box-shadow: 0 2px 10px rgba(56,189,248,0.3); }\n        .tab-content { display: none; }\n        .tab-content.active { display: block; }\n        .card { background: var(--card-bg); border: 1px solid var(--card-border); border-radius: 18px; padding: 16px; margin-bottom: 14px; box-shadow: 0 8px 24px rgba(0,0,0,0.35); backdrop-filter: blur(8px); }\n        .card-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; }\n        .card-title { font-size: 12px; font-weight: 700; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.8px; }\n        .score-pill-group { display: flex; align-items: center; gap: 6px; }\n        .badge { padding: 4px 10px; border-radius: 8px; font-size: 12px; font-weight: 800; display: inline-flex; align-items: center; }\n        .badge-score { background: rgba(56,189,248,0.15); color: var(--accent); border: 1px solid rgba(56,189,248,0.3); }\n        .badge-success { background: rgba(16,185,129,0.15); color: var(--success); border: 1px solid rgba(16,185,129,0.3); }\n        .badge-warning { background: rgba(245,158,11,0.15); color: var(--warning); border: 1px solid rgba(245,158,11,0.3); }\n        .badge-danger { background: rgba(239,68,68,0.15); color: var(--danger); border: 1px solid rgba(239,68,68,0.3); }\n        .badge-type { background: rgba(255,255,255,0.06); color: var(--text-secondary); font-size: 10px; font-weight: 600; border: 1px solid var(--card-border); padding: 2px 6px; border-radius: 6px; text-transform: uppercase; }\n        .metrics-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; margin-bottom: 14px; }\n        .metrics-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 14px; }\n        .metric-box { background: rgba(11,15,25,0.7); border: 1px solid var(--card-border); border-radius: 14px; padding: 12px; }\n        .metric-label { font-size: 10px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 4px; }\n        .metric-val { font-size: 21px; font-weight: 800; color: var(--text-primary); letter-spacing: -0.5px; }\n        .metric-unit { font-size: 12px; font-weight: 400; color: var(--text-secondary); margin-left: 3px; }\n        .corridor-banner { background: rgba(56,189,248,0.08); border: 1px solid rgba(56,189,248,0.3); border-radius: 14px; padding: 14px; margin-bottom: 12px; }\n        .corridor-title { font-size: 14px; font-weight: 800; color: var(--accent); margin-bottom: 4px; }\n        .corridor-desc { font-size: 12px; color: #CBD5E1; line-height: 1.45; }\n        .zone-table { width: 100%; border-collapse: collapse; margin-top: 6px; font-size: 12px; }\n        .zone-row { display: flex; justify-content: space-between; align-items: center; padding: 8px 10px; background: rgba(11,15,25,0.5); border: 1px solid var(--card-border); border-radius: 10px; margin-bottom: 6px; }\n        .zone-name { font-weight: 700; color: #F1F5F9; }\n        .zone-watts { font-weight: 800; color: var(--accent); }\n        .zone-range { font-size: 11px; color: var(--text-muted); margin-left: 6px; }\n        .stage-bar { display: flex; height: 14px; border-radius: 7px; overflow: hidden; margin: 8px 0 12px 0; background: #0B0F19; border: 1px solid var(--card-border); }\n        .stage-deep { background: var(--deep); }\n        .stage-rem { background: var(--rem); }\n        .stage-light { background: var(--light); }\n        .stage-awake { background: var(--awake); }\n        .stage-legend { display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px; font-size: 12px; color: var(--text-secondary); margin-top: 8px; }\n        .stage-item { display: flex; align-items: center; justify-content: space-between; background: rgba(11,15,25,0.5); padding: 6px 10px; border-radius: 8px; border: 1px solid var(--card-border); }\n        .stage-dot { display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 6px; }\n        .stage-time { font-weight: 700; color: var(--text-primary); }\n        .stage-pct { font-size: 10px; color: var(--text-muted); margin-left: 4px; }\n        .btn-sync { width: 100%; padding: 14px; background: var(--accent-gradient); border: none; border-radius: 14px; color: #fff; font-size: 14px; font-weight: 700; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 10px; box-shadow: 0 4px 20px rgba(56,189,248,0.35); transition: transform 0.15s, opacity 0.15s; margin-top: 10px; }\n        .btn-sync:active { transform: scale(0.98); opacity: 0.9; }\n        .btn-sync:disabled { opacity: 0.6; cursor: not-allowed; }\n        .form-group { margin-bottom: 16px; }\n        .form-label { display: block; font-size: 11px; font-weight: 700; color: var(--text-secondary); margin-bottom: 6px; text-transform: uppercase; letter-spacing: 0.5px; }\n        .form-input { width: 100%; padding: 12px; background: #0B0F19; border: 1px solid var(--card-border); border-radius: 12px; color: var(--text-primary); font-size: 14px; outline: none; transition: border-color 0.2s; }\n        .form-input:focus { border-color: var(--accent); }\n        .segmented-control { display: flex; background: #0B0F19; border: 1px solid var(--card-border); border-radius: 12px; padding: 3px; gap: 4px; }\n        .segmented-option { flex: 1; text-align: center; padding: 9px 6px; font-size: 12px; font-weight: 600; color: var(--text-secondary); border-radius: 9px; cursor: pointer; transition: all 0.2s; }\n        .segmented-option.selected { background: #1E293B; color: var(--accent); font-weight: 700; border: 1px solid rgba(56,189,248,0.3); }\n        .form-hint { font-size: 11px; color: var(--text-muted); margin-top: 6px; line-height: 1.4; }\n        .switch-row { display: flex; justify-content: space-between; align-items: center; padding: 12px 0; border-top: 1px solid var(--card-border); }\n        .toast { position: fixed; bottom: 24px; left: 16px; right: 16px; padding: 14px 20px; border-radius: 14px; font-size: 13px; font-weight: 600; text-align: center; z-index: 1000; display: none; box-shadow: 0 8px 24px rgba(0,0,0,0.6); }\n        .toast-success { background: #064E3B; color: #D1FAE5; border: 1px solid var(--success); }\n        .toast-error { background: #7F1D1D; color: #FEE2E2; border: 1px solid var(--danger); }\n        .history-item { background: rgba(11,15,25,0.7); border: 1px solid var(--card-border); border-radius: 14px; padding: 12px; margin-bottom: 10px; display: flex; justify-content: space-between; align-items: center; }\n        .history-date { font-weight: 700; font-size: 14px; color: var(--text-primary); margin-bottom: 3px; }\n        .history-meta { font-size: 12px; color: var(--text-secondary); }\n        .history-right { text-align: right; display: flex; flex-direction: column; align-items: flex-end; gap: 4px; }\n        .history-score { font-size: 20px; font-weight: 800; color: var(--accent); }\n        .history-sync-btn { background: #0284C7; border: none; color: #fff; font-size: 11px; font-weight: 700; padding: 4px 10px; border-radius: 7px; cursor: pointer; transition: background 0.15s; }\n        .history-sync-btn:active { background: #0369A1; }\n        .log-item { padding: 10px 12px; border-bottom: 1px solid var(--card-border); font-size: 12px; font-family: ui-monospace, SFMono-Regular, monospace; }\n        .log-time { color: var(--text-muted); font-size: 11px; margin-bottom: 2px; }\n        .log-msg { color: var(--text-primary); line-height: 1.3; }\n    </style>\n</head>\n");
        sb.append("<body>\n    <div class=\"header\">\n        <div class=\"brand\">\n            <div class=\"brand-icon\">&#9889;</div>\n            <div>\n                <h1>CyclingCoach Hub</h1>\n                <p id=\"status-line\">Dario (FTP 301 W, 66 kg)</p>\n            </div>\n        </div>\n        <button class=\"close-btn\" onclick=\"closeApp()\" title=\"Schließen\">&#10005;</button>\n    </div>\n\n    <div class=\"nav-tabs\">\n        <button class=\"nav-btn active\" onclick=\"setTab(0)\">Coach</button>\n        <button class=\"nav-btn\" onclick=\"setTab(1)\">Schlaf</button>\n        <button class=\"nav-btn\" onclick=\"setTab(2)\">Historie</button>\n        <button class=\"nav-btn\" onclick=\"setTab(3)\">Einstellungen</button>\n        <button class=\"nav-btn\" onclick=\"setTab(4)\">Logs</button>\n    </div>\n\n    <!-- COACH TAB -->\n    <div id=\"tab-0\" class=\"tab-content active\">\n        <!-- TAGES READINESS & FREIGABE -->\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\">Tages-Readiness & Freigabe</span>\n                <span class=\"badge badge-success\" id=\"coach-readiness-badge\">85% Optimal</span>\n            </div>\n            <div class=\"corridor-banner\">\n                <div class=\"corridor-title\" id=\"coach-clearance\">Freigabe: 100% Go</div>\n                <div class=\"corridor-desc\" id=\"coach-prescription\">Volle muskuläre und autonome Frische. Bereit für Z4 Schwellenblöcke oder lange Durability Ausfahrten über 2.000 kJ.</div>\n            </div>\n            <div class=\"metrics-grid\">\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">Tages-Korridor</div>\n                    <div class=\"metric-val\" style=\"font-size:16px; color:var(--accent);\" id=\"coach-corridor\">Z4 Schwelle: 270 bis 316 W</div>\n                </div>\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">Wonhalde 20m Best</div>\n                    <div class=\"metric-val\" style=\"font-size:16px;\">316,4 W<span class=\"metric-unit\">(4,79 W/kg)</span></div>\n                </div>\n            </div>\n        </div>\n\n        <!-- FORM & PERIODISIERUNG -->\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\">Formwerte & Periodisierung</span>\n                <span class=\"badge-type\">Intervals.icu</span>\n            </div>\n            <div class=\"metrics-grid-3\">\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">CTL (Fitness)</div>\n                    <div class=\"metric-val\" id=\"coach-ctl\">--</div>\n                </div>\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">ATL (Ermüdung)</div>\n                    <div class=\"metric-val\" id=\"coach-atl\">--</div>\n                </div>\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">TSB (Form)</div>\n                    <div class=\"metric-val\" id=\"coach-tsb\">--</div>\n                </div>\n            </div>\n            <div style=\"background:rgba(11,15,25,0.7); border:1px solid var(--card-border); border-radius:12px; padding:12px;\">\n                <div style=\"font-size:11px; font-weight:700; color:var(--text-secondary); text-transform:uppercase; margin-bottom:4px;\">Periodisierungsstatus (4-Wochen-Zyklus)</div>\n                <div style=\"font-size:12px; color:#F8FAFC; line-height:1.4;\" id=\"coach-periodization\">Woche 2 von 4: Progressive Aufbauphase. Wöchentlicher CTL-Zuwachs im 3 bis 5 Punkte Korridor halten. Jede vierte Woche ist eine Entlastungswoche mit ca. 60% Belastung.</div>\n            </div>\n        </div>\n\n        <!-- WATTKORRIDORE NACH FTP 301 W -->\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\">Wattkorridore (FTP 301 W, 66,0 kg)</span>\n                <span class=\"badge-type\">Outdoor</span>\n            </div>\n            <div class=\"zone-row\">\n                <div><span class=\"zone-name\">Z1 Rekompensation</span><span class=\"zone-range\">(&lt; 55 %)</span></div>\n                <span class=\"zone-watts\">&lt; 165 W</span>\n            </div>\n            <div class=\"zone-row\">\n                <div><span class=\"zone-name\">Z2 Grundlagenausdauer</span><span class=\"zone-range\">(55 bis 74 %)</span></div>\n                <span class=\"zone-watts\">165 bis 222 W</span>\n            </div>\n            <div class=\"zone-row\">\n                <div><span class=\"zone-name\">Z3 Mitteltempo</span><span class=\"zone-range\">(75 bis 90 %)</span></div>\n                <span class=\"zone-watts\">225 bis 270 W</span>\n            </div>\n            <div class=\"zone-row\">\n                <div><span class=\"zone-name\">Sweet Spot</span><span class=\"zone-range\">(88 bis 94 %)</span></div>\n                <span class=\"zone-watts\">265 bis 283 W</span>\n            </div>\n            <div class=\"zone-row\" style=\"border-color:rgba(56,189,248,0.4); background:rgba(56,189,248,0.06);\">\n                <div><span class=\"zone-name\" style=\"color:var(--accent);\">Z4 Schwellenleistung</span><span class=\"zone-range\">(90 bis 105 %)</span></div>\n                <span class=\"zone-watts\" style=\"color:#fff;\">270 bis 316 W</span>\n            </div>\n            <div class=\"zone-row\">\n                <div><span class=\"zone-name\">Z5 VO2max</span><span class=\"zone-range\">(105 bis 120 %)</span></div>\n                <span class=\"zone-watts\">316 bis 361 W</span>\n            </div>\n        </div>\n\n        <!-- SCHLAFAPNOE MONITORING (OSA) -->\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\">Schlafapnoe-Monitoring (OSA)</span>\n                <span class=\"badge badge-success\" id=\"coach-osa-badge\">Aktiv</span>\n            </div>\n            <div class=\"metrics-grid\">\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">AHI-Index</div>\n                    <div class=\"metric-val\" id=\"coach-osa-ahi\">--<span class=\"metric-unit\">/h</span></div>\n                </div>\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">SpO2 Tiefstwert</div>\n                    <div class=\"metric-val\" id=\"coach-osa-spo2\">--<span class=\"metric-unit\">%</span></div>\n                </div>\n            </div>\n            <div style=\"font-size:12px; color:var(--text-secondary); line-height:1.45;\" id=\"coach-osa-msg\">Kontinuierliche nächtliche Sauerstoffsättigungsüberwachung aktiv. Erfasst Sauerstoffabfälle und Atemaussetzer zur Sicherung der kardiovaskulären Regeneration.</div>\n        </div>\n\n        <!-- DURABILITY & ERNÄHRUNG -->\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\">Durability & Vegane Verpflegung</span>\n            </div>\n            <div style=\"margin-bottom:10px;\">\n                <div style=\"font-size:11px; font-weight:700; color:var(--text-secondary); text-transform:uppercase; margin-bottom:3px;\">Durability Kernvorgabe</div>\n                <div style=\"font-size:12px; color:#F8FAFC; line-height:1.4;\">Pacing-Stabilität der 2. gegen die 1. Hälfte prüfen. Gezielte Schwellenintervalle spät in langen Einheiten nach über 2.000 kJ Vorbelastung absolvieren. Unstrukturiertes Z3 Gefahre ohne klaren Trainingsreiz meiden.</div>\n            </div>\n            <div>\n                <div style=\"font-size:11px; font-weight:700; color:var(--text-secondary); text-transform:uppercase; margin-bottom:3px;\">Wettkampf-Fueling (Rein pflanzlich)</div>\n                <div style=\"font-size:12px; color:#F8FAFC; line-height:1.4;\" id=\"coach-fueling\">60 bis 90 g/h Kohlenhydrate über Maltodextrin und Datteln auf dem Rad zuführen. Keine Molke oder tierischen Proteine.</div>\n            </div>\n        </div>\n\n        <button class=\"btn-sync\" onclick=\"syncCurrentDay()\">\n            <span>&#8644;</span> Letzte Nacht zu Intervals.icu synchronisieren\n        </button>\n    </div>\n\n    <!-- SCHLAF TAB -->\n    <div id=\"tab-1\" class=\"tab-content\">\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\" id=\"dashboard-date\">Letzte Nacht</span>\n                <div class=\"score-pill-group\">\n                    <span class=\"badge badge-score\" id=\"sleep-score-badge\">Score: --</span>\n                    <span class=\"badge-type\" id=\"score-mode-badge\">Athletic</span>\n                </div>\n            </div>\n            <div class=\"metrics-grid\">\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">Schlafdauer</div>\n                    <div class=\"metric-val\" id=\"val-duration\">--<span class=\"metric-unit\"></span></div>\n                </div>\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">Ruhepuls</div>\n                    <div class=\"metric-val\" id=\"val-rhr\">--<span class=\"metric-unit\">bpm</span></div>\n                </div>\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">HRV (rMSSD/SDNN)</div>\n                    <div class=\"metric-val\" id=\"val-hrv\">--<span class=\"metric-unit\">ms</span></div>\n                </div>\n                <div class=\"metric-box\">\n                    <div class=\"metric-label\">Hauttemperatur</div>\n                    <div class=\"metric-val\" id=\"val-temp\">--<span class=\"metric-unit\">&deg;C</span></div>\n                </div>\n            </div>\n            <div class=\"stage-card\">\n                <div class=\"stage-title-row\" style=\"display:flex; justify-content:space-between; font-size:12px; font-weight:600; color:var(--text-secondary); margin-bottom:6px;\">\n                    <span>Schlafphasen</span>\n                    <span id=\"lbl-efficiency\">-- Effizienz</span>\n                </div>\n                <div class=\"stage-bar\">\n                    <div id=\"bar-deep\" class=\"stage-deep\" style=\"width: 25%\"></div>\n                    <div id=\"bar-rem\" class=\"stage-rem\" style=\"width: 20%\"></div>\n                    <div id=\"bar-light\" class=\"stage-light\" style=\"width: 45%\"></div>\n                    <div id=\"bar-awake\" class=\"stage-awake\" style=\"width: 10%\"></div>\n                </div>\n                <div class=\"stage-legend\">\n                    <div class=\"stage-item\">\n                        <span><span class=\"stage-dot\" style=\"background: var(--deep)\"></span>Tiefschlaf</span>\n                        <span><span class=\"stage-time\" id=\"lbl-deep\">--</span><span class=\"stage-pct\" id=\"pct-deep\"></span></span>\n                    </div>\n                    <div class=\"stage-item\">\n                        <span><span class=\"stage-dot\" style=\"background: var(--rem)\"></span>REM-Schlaf</span>\n                        <span><span class=\"stage-time\" id=\"lbl-rem\">--</span><span class=\"stage-pct\" id=\"pct-rem\"></span></span>\n                    </div>\n                    <div class=\"stage-item\">\n                        <span><span class=\"stage-dot\" style=\"background: var(--light)\"></span>Leichtschlaf</span>\n                        <span><span class=\"stage-time\" id=\"lbl-light\">--</span><span class=\"stage-pct\" id=\"pct-light\"></span></span>\n                    </div>\n                    <div class=\"stage-item\">\n                        <span><span class=\"stage-dot\" style=\"background: var(--awake)\"></span>Wachzeit</span>\n                        <span><span class=\"stage-time\" id=\"lbl-awake\">--</span><span class=\"stage-pct\" id=\"pct-awake\"></span></span>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <button class=\"btn-sync\" onclick=\"syncCurrentDay()\">\n            <span>&#8644;</span> Zu Intervals.icu übertragen\n        </button>\n    </div>\n\n    <!-- HISTORIE TAB -->\n    <div id=\"tab-2\" class=\"tab-content\">\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\">Historie (Letzte 30 Tage)</span>\n            </div>\n            <div id=\"history-list\">Lade Aufzeichnungen aus ring_conn.db...</div>\n        </div>\n    </div>\n\n    <!-- EINSTELLUNGEN TAB -->\n    <div id=\"tab-3\" class=\"tab-content\">\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\">Intervals.icu Konfiguration</span>\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">Athlete ID</label>\n                <input class=\"form-input\" id=\"cfg-athlete-id\" placeholder=\"i557347\">\n                <div class=\"form-hint\">Deine persönliche Intervals.icu Athleten-Kennung.</div>\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">API Key</label>\n                <input class=\"form-input\" id=\"cfg-api-key\" type=\"password\" placeholder=\"Intervals API Key\">\n                <div class=\"form-hint\">Erstellt unter Intervals.icu &gt; Settings &gt; Developer API.</div>\n            </div>\n            <div class=\"form-group\">\n                <label class=\"form-label\">Schlaf-Score Berechnungsmodell</label>\n                <div class=\"segmented-control\">\n                    <div class=\"segmented-option selected\" id=\"opt-score-athletic\" onclick=\"selectScoreSource('athletic')\">Athletic (Empfohlen)</div>\n                    <div class=\"segmented-option\" id=\"opt-score-ringconn\" onclick=\"selectScoreSource('ringconn')\">RingConn Original</div>\n                </div>\n                <div class=\"form-hint\" id=\"score-source-hint\">Athletic-Formel: Nicht-lineare Schlafdauer-Bewertung, hohe Tief- und REM-Schlafgewichtung, kalibriert für Radsportler.</div>\n            </div>\n            <div class=\"switch-row\">\n                <span class=\"form-label\" style=\"margin-bottom:0\">Automatischer Hintergrund-Sync</span>\n                <input type=\"checkbox\" id=\"cfg-auto-sync\" checked style=\"transform: scale(1.3);\">\n            </div>\n            <button class=\"btn-sync\" onclick=\"saveConfig()\">Einstellungen speichern</button>\n            <div class=\"form-group\" style=\"margin-top: 20px; padding-top: 14px; border-top: 1px solid var(--card-border);\">\n                <label class=\"form-label\">Lokaler Datenexport (Backup / Google Drive)</label>\n                <button class=\"btn-sync\" type=\"button\" onclick=\"triggerLocalBackup()\" style=\"background: #1E293B; border: 1px solid rgba(56,189,248,0.5); color: #38BDF8; box-shadow: none;\">In Download/IntervalsDirect sichern</button>\n                <div class=\"form-hint\" id=\"backup-status-hint\">Exportiert RingConn_Wellness_Master.json und .csv in den Gerätespeicher.</div>\n            </div>\n        </div>\n    </div>\n\n    <!-- LOGS TAB -->\n    <div id=\"tab-4\" class=\"tab-content\">\n        <div class=\"card\">\n            <div class=\"card-header\">\n                <span class=\"card-title\">Synchronisations-Protokoll</span>\n            </div>\n            <div id=\"logs-list\" style=\"max-height: 420px; overflow-y: auto;\">Noch keine Protokolle vorhanden.</div>\n        </div>\n    </div>\n\n    <div id=\"toast\" class=\"toast\"></div>\n\n    <script>\n        let currentHistory = [];\n        let latestDate = \"\";\n        let currentScoreSource = \"athletic\";\n\n        function showToast(msg, isError) {\n            const t = document.getElementById(\"toast\");\n            t.innerText = msg;\n            t.className = \"toast \" + (isError ? \"toast-error\" : \"toast-success\");\n            t.style.display = \"block\";\n            setTimeout(() => { t.style.display = \"none\"; }, 3500);\n        }\n\n        function triggerLocalBackup() {\n            if (!window.IntervalsBridge) return;\n            const hint = document.getElementById(\"backup-status-hint\");\n            hint.innerText = \"Exportiere Datensätze...\";\n            try {\n                const res = window.IntervalsBridge.exportLocalBackup();\n                hint.innerText = res;\n                showToast(res, false);\n            } catch (e) {\n                hint.innerText = \"Fehler: \" + e.message;\n                showToast(\"Fehler: \" + e.message, true);\n            }\n        }\n\n        function setTab(idx) {\n            document.querySelectorAll(\".nav-btn\").forEach((b, i) => b.classList.toggle(\"active\", i === idx));\n            document.querySelectorAll(\".tab-content\").forEach((c, i) => c.classList.toggle(\"active\", i === idx));\n            if (idx === 0) loadCoachTab();\n            if (idx === 2) renderHistory();\n            if (idx === 4) loadLogs();\n        }\n\n        function selectScoreSource(src) {\n            currentScoreSource = src;\n            document.getElementById(\"opt-score-athletic\").classList.toggle(\"selected\", src === \"athletic\");\n            document.getElementById(\"opt-score-ringconn\").classList.toggle(\"selected\", src === \"ringconn\");\n            const hint = document.getElementById(\"score-source-hint\");\n            if (src === \"athletic\") {\n                hint.innerText = \"Athletic-Formel: Nicht-lineare Schlafdauer-Bewertung, hohe Tief- und REM-Schlafgewichtung, kalibriert für Radsportler.\";\n            } else {\n                hint.innerText = \"RingConn Original: Verwendet den unveränderten Schlaf-Score direkt aus dem RingConn Algorithmus.\";\n            }\n            if (currentHistory && currentHistory.length > 0) {\n                displayDashboard(currentHistory[0]);\n            }\n        }\n\n        function closeApp() {\n            if (window.IntervalsBridge) window.IntervalsBridge.close();\n        }\n\n        function loadInitialData() {\n            if (!window.IntervalsBridge) return;\n            try {\n                const settings = JSON.parse(window.IntervalsBridge.getSettings());\n                document.getElementById(\"cfg-athlete-id\").value = settings.athleteId || \"\";\n                document.getElementById(\"cfg-api-key\").value = settings.apiKey || \"\";\n                document.getElementById(\"cfg-auto-sync\").checked = settings.autoSync !== false;\n                selectScoreSource(settings.scoreSource || \"athletic\");\n                if (settings.lastSyncStatus) {\n                    document.getElementById(\"status-line\").innerText = settings.lastSyncStatus;\n                }\n                currentHistory = JSON.parse(window.IntervalsBridge.getSleepHistory(30));\n                if (currentHistory && currentHistory.length > 0) {\n                    displayDashboard(currentHistory[0]);\n                }\n                loadCoachTab();\n            } catch (e) {\n                console.error(e);\n            }\n        }\n\n        function loadCoachTab() {\n            if (!window.IntervalsBridge || !window.IntervalsBridge.getCoachData) return;\n            try {\n                const raw = window.IntervalsBridge.getCoachData();\n                const c = JSON.parse(raw);\n                if (!c) return;\n                \n                const badge = document.getElementById(\"coach-readiness-badge\");\n                badge.innerText = c.readinessScore + \"% \" + (c.readinessLabel || \"Optimal\");\n                if (c.readinessScore >= 80) {\n                    badge.className = \"badge badge-success\";\n                } else if (c.readinessScore >= 55) {\n                    badge.className = \"badge badge-warning\";\n                } else {\n                    badge.className = \"badge badge-danger\";\n                }\n                \n                document.getElementById(\"coach-clearance\").innerText = c.clearance || \"Freigabe: 100% Go\";\n                document.getElementById(\"coach-prescription\").innerText = c.prescription || \"\";\n                document.getElementById(\"coach-corridor\").innerText = c.corridor || \"Z4 Schwelle: 270 bis 316 W\";\n                document.getElementById(\"coach-ctl\").innerText = (c.ctl !== undefined && c.ctl > 0) ? Math.round(c.ctl * 10) / 10 : \"--\";\n                document.getElementById(\"coach-atl\").innerText = (c.atl !== undefined && c.atl > 0) ? Math.round(c.atl * 10) / 10 : \"--\";\n                document.getElementById(\"coach-tsb\").innerText = c.tsb !== undefined ? (c.tsb > 0 ? \"+\" : \"\") + (Math.round(c.tsb * 10) / 10) : \"--\";\n                if (c.periodizationText) document.getElementById(\"coach-periodization\").innerText = c.periodizationText;\n                if (c.veganFueling) document.getElementById(\"coach-fueling\").innerText = c.veganFueling;\n                \n                if (c.osa) {\n                    const osaBadge = document.getElementById(\"coach-osa-badge\");\n                    osaBadge.innerText = c.osa.status || \"Aktiv\";\n                    if (c.osa.latestAhi !== undefined) {\n                        document.getElementById(\"coach-osa-ahi\").innerHTML = (Math.round(c.osa.latestAhi * 10) / 10) + \"<span class=\\\"metric-unit\\\">/h</span>\";\n                    }\n                    if (c.osa.spo2Low !== undefined && c.osa.spo2Low > 0) {\n                        document.getElementById(\"coach-osa-spo2\").innerHTML = c.osa.spo2Low + \"<span class=\\\"metric-unit\\\">%</span>\";\n                    }\n                    if (c.osa.message) {\n                        document.getElementById(\"coach-osa-msg\").innerText = c.osa.message;\n                    }\n                }\n            } catch (e) {\n                console.error(\"Coach load error:\", e);\n            }\n        }\n\n        function displayDashboard(d) {\n            latestDate = d.date || \"\";\n            document.getElementById(\"dashboard-date\").innerText = d.date || \"Letzte Nacht\";\n            \n            const displayScore = currentScoreSource === \"ringconn\" ? (d.ringconnScore || d.score) : (d.athleticScore || d.score);\n            document.getElementById(\"sleep-score-badge\").innerText = \"Score: \" + (displayScore || \"--\");\n            document.getElementById(\"score-mode-badge\").innerText = currentScoreSource === \"ringconn\" ? \"RingConn\" : \"Athletic\";\n            \n            const totalMins = d.sleepDurationMinutes || 0;\n            const h = Math.floor(totalMins / 60);\n            const m = totalMins % 60;\n            document.getElementById(\"val-duration\").innerHTML = (h > 0 ? h + \"h \" : \"\") + m + \"<span class=\\\"metric-unit\\\">m</span>\";\n            document.getElementById(\"val-rhr\").innerHTML = (d.restingHr || \"--\") + \"<span class=\\\"metric-unit\\\">bpm</span>\";\n            document.getElementById(\"val-hrv\").innerHTML = (d.hrv || \"--\") + \"<span class=\\\"metric-unit\\\">ms</span>\";\n            const temp = d.tempOffset !== undefined ? (d.tempOffset > 0 ? \"+\" : \"\") + d.tempOffset : \"--\";\n            document.getElementById(\"val-temp\").innerHTML = temp + \"<span class=\\\"metric-unit\\\">&deg;C</span>\";\n\n            const deep = d.deepMinutes || 0;\n            const rem = d.remMinutes || 0;\n            const light = d.lightMinutes || 0;\n            const awake = d.awakeMinutes || 0;\n            const sum = (deep + rem + light + awake) || 1;\n            \n            const deepPct = Math.round(deep / sum * 100);\n            const remPct = Math.round(rem / sum * 100);\n            const lightPct = Math.round(light / sum * 100);\n            const awakePct = Math.round(awake / sum * 100);\n            \n            document.getElementById(\"bar-deep\").style.width = deepPct + \"%\";\n            document.getElementById(\"bar-rem\").style.width = remPct + \"%\";\n            document.getElementById(\"bar-light\").style.width = lightPct + \"%\";\n            document.getElementById(\"bar-awake\").style.width = awakePct + \"%\";\n            \n            document.getElementById(\"lbl-deep\").innerText = deep + \"m\";\n            document.getElementById(\"pct-deep\").innerText = \"(\" + deepPct + \"%)\";\n            document.getElementById(\"lbl-rem\").innerText = rem + \"m\";\n            document.getElementById(\"pct-rem\").innerText = \"(\" + remPct + \"%)\";\n            document.getElementById(\"lbl-light\").innerText = light + \"m\";\n            document.getElementById(\"pct-light\").innerText = \"(\" + lightPct + \"%)\";\n            document.getElementById(\"lbl-awake\").innerText = awake + \"m\";\n            document.getElementById(\"pct-awake\").innerText = \"(\" + awakePct + \"%)\";\n            \n            const eff = sum > 0 ? Math.round(totalMins / sum * 100) : 0;\n            document.getElementById(\"lbl-efficiency\").innerText = eff + \"% Effizienz\";\n        }\n\n        function renderHistory() {\n            const container = document.getElementById(\"history-list\");\n            if (!currentHistory || currentHistory.length === 0) {\n                container.innerHTML = \"<p style=\\\"color:var(--text-muted);text-align:center;padding:20px;\\\">Keine Schlafaufzeichnungen vorhanden</p>\";\n                return;\n            }\n            let html = \"\";\n            currentHistory.forEach(item => {\n                const totalMins = item.sleepDurationMinutes || 0;\n                const h = Math.floor(totalMins / 60);\n                const m = totalMins % 60;\n                const itemScore = currentScoreSource === \"ringconn\" ? (item.ringconnScore || item.score) : (item.athleticScore || item.score);\n                html += \"<div class=\\\"history-item\\\">\" +\n                    \"<div>\" +\n                        \"<div class=\\\"history-date\\\">\" + item.date + \"</div>\" +\n                        \"<div class=\\\"history-meta\\\">\" + h + \"h \" + m + \"m &bull; Ruhepuls: \" + (item.restingHr || \"--\") + \" bpm &bull; HRV: \" + (item.hrv || \"--\") + \" ms</div>\" +\n                    \"</div>\" +\n                    \"<div class=\\\"history-right\\\">\" +\n                        \"<div class=\\\"history-score\\\">\" + (itemScore || \"--\") + \"</div>\" +\n                        \"<button class=\\\"history-sync-btn\\\" onclick=\\\"syncSingle('\" + item.date + \"')\\\">Sync</button>\" +\n                    \"</div>\" +\n                \"</div>\";\n            });\n            container.innerHTML = html;\n        }\n\n        function loadLogs() {\n            if (!window.IntervalsBridge) return;\n            try {\n                const logs = JSON.parse(window.IntervalsBridge.getLogs());\n                const container = document.getElementById(\"logs-list\");\n                if (!logs || logs.length === 0) {\n                    container.innerHTML = \"<p style=\\\"color:var(--text-muted);padding:14px;\\\">Noch keine Protokolle verzeichnet.</p>\";\n                    return;\n                }\n                let html = \"\";\n                logs.forEach(l => {\n                    html += \"<div class=\\\"log-item\\\"><div class=\\\"log-time\\\">\" + l.time + \"</div><div class=\\\"log-msg\\\">\" + l.message + \"</div></div>\";\n                });\n                container.innerHTML = html;\n            } catch (e) { console.error(e); }\n        }\n\n        function saveConfig() {\n            if (!window.IntervalsBridge) return;\n            const athleteId = document.getElementById(\"cfg-athlete-id\").value;\n            const apiKey = document.getElementById(\"cfg-api-key\").value;\n            const autoSync = document.getElementById(\"cfg-auto-sync\").checked;\n            window.IntervalsBridge.saveSettings(athleteId, apiKey, autoSync, currentScoreSource);\n            showToast(\"Einstellungen erfolgreich gespeichert!\", false);\n            if (currentHistory && currentHistory.length > 0) {\n                displayDashboard(currentHistory[0]);\n            }\n        }\n\n        function syncCurrentDay() {\n            if (!latestDate) {\n                showToast(\"Kein Datensatz zur Übertragung gefunden.\", true);\n                return;\n            }\n            syncSingle(latestDate);\n        }\n\n        function syncSingle(d) {\n            if (!window.IntervalsBridge) return;\n            showToast(\"Übertrage \" + d + \" zu Intervals.icu...\", false);\n            setTimeout(() => {\n                try {\n                    const res = JSON.parse(window.IntervalsBridge.syncDate(d));\n                    if (res.success) {\n                        showToast(\"Erfolgreich übertragen: \" + d, false);\n                        document.getElementById(\"status-line\").innerText = \"Letzter Sync: \" + d + \" OK\";\n                        loadCoachTab();\n                    } else {\n                        showToast(\"Sync-Fehler: \" + res.message, true);\n                    }\n                } catch (e) {\n                    showToast(\"Fehler bei Übertragung: \" + e, true);\n                }\n            }, 100);\n        }\n\n        window.onload = loadInitialData;\n    </script>\n</body>\n</html>");
        return sb.toString();
    }
}
